"""Exercise the evidence URL cells generated by Aurora's Excel exporter."""

import io
from pathlib import Path
import shutil
import subprocess
import unittest
from xml.etree import ElementTree
from zipfile import ZipFile


@unittest.skipUnless(shutil.which("node"), "The Excel exporter test needs Node.js")
class ExcelEvidenceSelectionTests(unittest.TestCase):
    def test_negative_exports_names_searched_and_selected_records_keep_snapshots(self):
        root = Path(__file__).resolve().parents[1]
        program = r"""
const fs = require('node:fs');
const vm = require('node:vm');
global.window = {};
global.location = {origin: 'https://staging.example.test'};
for (const filename of ['identity-review.js', 'excel-export.js'])
  vm.runInThisContext(fs.readFileSync('web-staging/' + filename, 'utf8'));
const snapshot = '/state-snapshots/' + 'a'.repeat(64) + '.pdf';
const history = '/state-evidence/' + 'b'.repeat(64) + '/search-history.pdf';
const both = {success: true, status: 'Not Registered',
  evidence_url: snapshot, search_history_url: history};
const cases = [
  {...both, state: 'AR'},
  {...both, state: 'AR', evidence_bundle_url: '/state-evidence/' + 'c'.repeat(64) + '/evidence.zip'},
  {...both, state: 'IL', status: 'Not Registered / Non-Compliant'},
  {...both, state: 'NY', status: 'Current'},
  {...both, state: 'CA', matched_registry_name: 'Example Charity', matched_registry_identifier: '123',
    raw_status_text: 'Registration Type: Charitable Organization | Registration Status: Not Registered'},
  {...both, state: 'CA'},
  {...both, state: 'AR', success: false, status: 'Unable to Verify', evidence_url: '',
    status_reason: 'AR_REQUIRED_SEARCH_INCOMPLETE'},
  {state:'GA', status:'Current', matched_registry_identifier:'GA41', identity_review:{candidates:[
    {name:'Good charity', identifier:'GA41', evidence_url:snapshot}] }},
  {state:'RI', status:'Unable to Confirm', identity_review:{candidates:[
    {name:'First candidate', identifier:'RI1', evidence_url:snapshot},
    {name:'Second candidate', identifier:'RI2', evidence_url:snapshot},
    {name:'Rejected candidate', identifier:'RI3', evidence_url:snapshot, decision:'reject'},
    {name:'Untrusted candidate', identifier:'RI4', evidence_url:'https://wrong.example/file.pdf'}] }},
];
window.CCExcelExport.build(cases).arrayBuffer()
  .then(bytes => process.stdout.write(Buffer.from(bytes)));
"""
        run = subprocess.run(["node", "-e", program], cwd=root, capture_output=True, check=True)
        with ZipFile(io.BytesIO(run.stdout)) as workbook:
            sheet = ElementTree.fromstring(workbook.read("xl/worksheets/sheet2.xml"))
            candidates = ElementTree.fromstring(workbook.read("xl/worksheets/sheet3.xml"))
            self.assertEqual([c.attrib["ref"] for c in candidates.findall(".//{*}hyperlink")], ["E2", "E3", "E4"])
            self.assertEqual([c.attrib["ref"] for c in sheet.findall(".//{*}hyperlink")][-1], "C9")
        cells = {cell.attrib["r"]: "".join(cell.itertext()) for cell in sheet.findall(".//{*}c")}
        snapshots = "https://staging.example.test/state-snapshots/" + "a" * 64 + ".pdf"
        history = "https://staging.example.test/state-evidence/" + "b" * 64 + "/search-history.pdf"
        self.assertEqual(
            [(cells[f"C{row}"], cells[f"I{row}"]) for row in range(2, 11)],
            [(history, "Search history"), ("Names searched unavailable", ""), (history, "Search history"),
             (snapshots, "State snapshot"), (snapshots, "State snapshot"), (history, "Search history"),
             (history, "Search attempts"), (snapshots, "Candidate snapshot"), ("See Candidate Evidence tab", "")],
        )

    def test_alerts_hyperlinks_stay_in_the_evidence_column(self):
        root = Path(__file__).resolve().parents[1]
        program = r"""
global.window={};
require('./web-staging/excel-export.js');
const url='https://staging.example.test/api/alerts/evidence/42';
window.CCExcelExport.buildAlerts([['Example','12-3456789','NV','Old','New','Date','Now','',''+url]])
    .arrayBuffer().then(bytes=>process.stdout.write(Buffer.from(bytes)));
"""
        run = subprocess.run(["node", "-e", program], cwd=root, capture_output=True, check=True)
        with ZipFile(io.BytesIO(run.stdout)) as book:
            sheet = ElementTree.fromstring(book.read("xl/worksheets/sheet1.xml"))
            relation = ElementTree.fromstring(book.read("xl/worksheets/_rels/sheet1.xml.rels"))
            self.assertEqual(sheet.find(".//{*}hyperlink").attrib["ref"], "I2")
            self.assertEqual(relation[0].attrib["Target"], "https://staging.example.test/api/alerts/evidence/42")
